const state={items:[],category:"全部",query:""};
const grid=document.querySelector("#toolGrid"),empty=document.querySelector("#toolEmpty"),filters=document.querySelector("#toolFilters"),queryInput=document.querySelector("#toolQuery");
const kindLabel={integrated:"已整合到 PaperTrace",online:"在线工具",source:"源码仓库"};
function categories(){return ["全部",...new Set(state.items.map(item=>item.category))];}
function renderFilters(){filters.innerHTML=categories().map(category=>`<button class="tool-filter${category===state.category?" active":""}" data-category="${escapeHtml(category)}">${escapeHtml(category)}</button>`).join("");filters.querySelectorAll("button").forEach(button=>button.addEventListener("click",()=>{state.category=button.dataset.category;renderFilters();render();}));}
function visible(){const needle=state.query.trim().toLowerCase();return state.items.filter(item=>(state.category==="全部"||item.category===state.category)&&(!needle||[item.title,item.short,item.description,item.category,...item.tags].join(" ").toLowerCase().includes(needle)));}
function card(item){const action=item.open?`<a class="btn primary" href="${escapeAttr(item.open)}"${isExternal(item.open)?' target="_blank" rel="noopener"':''}>${item.kind==="integrated"?"进入工具":"打开工具"} ↗</a>`:"";return `<article class="tool-card" data-kind="${escapeAttr(item.kind)}"><div class="tool-card-top"><span class="tool-icon" aria-hidden="true">${escapeHtml(item.icon)}</span><span class="tool-kind">${escapeHtml(kindLabel[item.kind]||"项目")}</span></div><h2>${escapeHtml(item.title)}</h2><p>${escapeHtml(item.description)}</p><div class="tool-tags">${item.tags.map(tag=>`<span class="tool-tag">${escapeHtml(tag)}</span>`).join("")}</div><div class="tool-card-bottom"><span class="tool-kind">${escapeHtml(item.short)}</span><div class="tool-actions">${action}<a class="text-btn" href="${escapeAttr(item.source)}" target="_blank" rel="noopener">源码 ↗</a></div></div></article>`;}
function render(){const items=visible();grid.innerHTML=items.map(card).join("");empty.hidden=items.length>0;}
function isExternal(url){return /^https?:/i.test(url);}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[char]));}
function escapeAttr(value){return escapeHtml(value);}
queryInput.addEventListener("input",()=>{state.query=queryInput.value;render();});
fetch("data/tools.json").then(response=>{if(!response.ok)throw new Error(`tools.json ${response.status}`);return response.json();}).then(items=>{state.items=items;document.querySelector("#toolCount").textContent=items.length;document.querySelector("#toolStatus").textContent="公开项目已归档";renderFilters();render();}).catch(error=>{document.querySelector("#toolStatus").textContent="清单读取失败";grid.innerHTML=`<div class="error-box">学习工具清单加载失败：${escapeHtml(error.message)}</div>`;});
